      "glossary": {
        "title": "Glossary",
        "lead": "The words of the model, two sentences each.",
        "more": "On the canvas",
        "term": {
          "prior": {
            "name": "Prior",
            "what": "What you believe about a quantity before seeing the data, written as a distribution. The model combines it with the data.",
          },
          "likelihood": {
            "name": "Likelihood",
            "what": "How the observed data come from the quantities of the model. It is the bridge between the model and the rows.",
          },
          "posterior": {
            "name": "Posterior",
            "what": "What is known about a quantity after seeing the data. The flow that runs the model gives it back.",
          },
          "hyperprior": {
            "name": "Hyperprior",
            "what": "The prior of a quantity that sets other priors, such as the spread between schools. Its value moves the priors that read it.",
          },
          "box": {
            "name": "Box",
            "what": "Repeats the nodes it holds once for each group: a school, a district. A box inside another is a nested group.",
          },
          "nonCentred": {
            "name": "Non-centred",
            "what": "A way of writing the groups that helps the sampler when each group has few rows. It is the default, and it changes box by box.",
          },
          "standardized": {
            "name": "Standardized",
            "what": "A column centred on its mean and divided by its standard deviation. The flow node does it; the result gives the coefficients on both scales.",
          },
          "data": {
            "name": "Data",
            "what": "A column of the table that the flow node binds when the model runs. On the canvas, a filled rectangle.",
          },
          "parameter": {
            "name": "Parameter",
            "what": "An unknown quantity with its prior: what the model estimates. On the canvas, a pill.",
          },
          "linearPredictor": {
            "name": "Linear predictor",
            "what": "An intercept plus each predictor times its coefficient. It is the usual heart of a regression.",
          },
          "state": {
            "name": "Latent state",
            "what": "A hidden value that moves along a time series, step by step. The data are measured around it.",
          },
          "effects": {
            "name": "Correlated effects",
            "what": "Several effects per group, such as a level and a slope, that vary together. Their correlation has a prior of its own, the LKJ.",
          },
          "lag": {
            "name": "lag",
            "what": "lag(y, k) is the value of y k rows earlier in the series. The first k rows of each series have none.",
          },
        },
      },
      "explain": {
        "parameter": "A quantity the model does not know and estimates from the data. Its prior says what is believed about it before the data; the chart draws that belief.",
        "transformed": "A value computed from other nodes with a formula. It adds nothing unknown: it is a name for a formula used elsewhere.",
        "linear_predictor": "An intercept plus a coefficient times each predictor, row by row. A likelihood usually takes it as its centre.",
        "likelihood": "How the observed data come about from the other nodes. It is where the model meets the rows of the table.",
        "state": "A hidden value along the series: it starts from its prior and moves by a normal step at each row. The data are measured around it.",
        "correlated_effects": "Several effects for each group, such as a level and a slope, that vary together. Each has a mean and a spread between groups; their correlation has an LKJ prior.",
        "data_real": "A column of numbers that the flow node binds when the model runs. As a predictor it is standardized unless the switch is off.",
        "data_int": "A column of whole numbers, such as counts or 0 and 1. It is never standardized.",
        "data_group_index": "The column that says which group each row belongs to. Its values are the units of its box.",
        "data_category": "A text column with a few values, used as a predictor. The first value in text order is the reference; each other one gets its own coefficient.",
        "data_time": "The order of the rows in a time series. It is never a number in a formula: lag and latent states follow it.",
        "rows": "The box of the rows of the data: one unit per row the flow node binds. The data, the values computed per row and the likelihood sit here.",
        "group": "A level of a hierarchy: what it holds is repeated once per unit, such as one value per school. The data say how many units there are.",
      },
